/**
 * A fold across the closed position hands off in steps, and the outgoing display first reports
 * the incoming one's orientation, so an unsettled screen's orientation does not say how the
 * phone is held. Stands such as Tent can also rest unsettled on the cover.
 */
export function duoScreenSettled(screen) {
    const angle = screen.hingeAngle ?? (screen.screenId === 1 ? 0 : 180);
    return (screen.screenId === 1) === (angle === 0);
}
/**
 * The inner panel is mounted a quarter turn from the cover, so its landscape
 * orientation means a vertical phone.
 */
export function duoFoldState(screen) {
    const angle = screen.hingeAngle ?? (screen.screenId === 1 ? 0 : 180);
    const landscape = screen.orientation.startsWith("landscape");
    return {
        fold: angle === 0 ? "closed" : angle === 180 ? "open" : "half",
        stand: screen.hingePose === "laptop" || screen.hingePose === "tent",
        phoneVertical: screen.screenId === 1 ? !landscape : landscape,
        settled: duoScreenSettled(screen),
    };
}
export function duoHoldOrientation(vertical, screenId) {
    if (screenId === 1)
        return vertical ? "portrait" : "landscape_left";
    return vertical ? "landscape_left" : "portrait_upside_down";
}
export function createDuoControl(options) {
    let nextId = 1;
    let active = null;
    let queued = null;
    let timer = null;
    const publish = (error = null) => options.onChange({ pending: !!active, requested: queued ?? active?.command ?? null, error });
    const clear = (error = null) => {
        if (timer)
            clearTimeout(timer);
        timer = null;
        active = null;
        queued = null;
        publish(error);
    };
    const drain = () => {
        if (active || !queued)
            return;
        active = { requestId: nextId++, command: queued };
        queued = null;
        const id = active.requestId;
        timer = setTimeout(() => {
            if (active?.requestId === id)
                clear("Device control timed out. Its position is unknown.");
        }, options.timeoutMs ?? 5_000);
        publish();
        if (!options.send(active))
            clear("Device is disconnected.");
    };
    return {
        enqueue(command) {
            if (command.control === "angle" &&
                (!Number.isFinite(command.value) || command.value < 0 || command.value > 180))
                return;
            queued = command;
            if (active)
                publish();
            else
                drain();
        },
        receive(reply) {
            if (!active || reply.requestId !== active.requestId)
                return;
            if (timer)
                clearTimeout(timer);
            timer = null;
            active = null;
            if (!reply.ok) {
                clear(reply.error ?? "Device control failed. Its position is unknown.");
                return;
            }
            if (queued)
                drain();
            else
                publish();
        },
        clear,
    };
}
export function createDuoPinch(options) {
    let angle = null;
    return {
        begin(x, y) {
            if (!options.contains(x, y))
                return false;
            angle = Math.max(0, Math.min(180, options.angle()));
            return true;
        },
        move(logScale) {
            if (angle === null || !Number.isFinite(logScale))
                return;
            const next = Math.max(0, Math.min(180, angle + logScale * 120));
            if (next === angle)
                return;
            angle = next;
            options.change(next);
        },
        end() {
            if (angle === null)
                return;
            angle = null;
            options.change(null);
        },
        get active() {
            return angle !== null;
        },
    };
}
